def topo_sort(graph):
    # Build in-degree and a set of all nodes
    in_degree = {}
    all_nodes = set(graph.keys())
    for node, prereqs in graph.items():
        in_degree.setdefault(node, 0)
        for p in prereqs:
            in_degree.setdefault(p, 0)
            in_degree[p] += 1
            all_nodes.add(p)

    # Min-heap of nodes with in_degree == 0
    import heapq
    heap = [n for n in all_nodes if in_degree.get(n, 0) == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        # For each node that depends on this node, reduce its in-degree
        for other, prereqs in graph.items():
            if node in prereqs:
                in_degree[other] -= 1
                if in_degree[other] == 0:
                    heapq.heappush(heap, other)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")
    return result
